initJs:
function(container, apiUrl, tables) {
  let editingModelId = null;

  // 1. 再描画関数の定義
  function renderRows(rows) {
    const tbody = container.querySelector("#model-list-tbody");
    tbody.innerHTML = rows.map(r => `
      <tr data-id="${r.id}">
        <td>${r.モデル名 || ""}</td>
        <td>${r.対象店舗名 || ""}</td>
        <td>${r.商品カテゴリ || ""}</td>
        <td>${r.アルゴリズム || ""}</td>
        <td>${r.精度目標値 || ""}%</td>
        <td>${r.作成日時 ? new Date(r.作成日時).toLocaleDateString() : ""}</td>
        <td>
          <button class="action-btn secondary edit-btn" data-id="${r.id}">設定変更</button>
          <button class="action-btn secondary delete-btn" data-id="${r.id}">削除</button>
        </td>
      </tr>
    `).join("");
  }

  // 店舗一覧を読み込み
  function loadStores() {
    const storeSelect = container.querySelector("#target-store");
    if (tables[1] && tables[1].records) {
      storeSelect.innerHTML = '<option value="">選択してください</option>' + 
        tables[1].records.map(store => 
          `<option value="${store.id}">${store.店舗名}</option>`
        ).join("");
    }
  }

  // 重み付け合計値を計算・表示
  function updateWeightTotal() {
    const weightInputs = container.querySelectorAll(".weight-input");
    let total = 0;
    weightInputs.forEach(input => {
      total += parseInt(input.value) || 0;
    });
    container.querySelector("#weight-total").textContent = total;

    // 100%でない場合は警告表示
    const totalElement = container.querySelector("#weight-total");
    if (total !== 100) {
      totalElement.style.color = "#ff6a6a";
    } else {
      totalElement.style.color = "var(--text)";
    }
  }

  // 学習率スライダーの値表示更新
  function updateLearningRateDisplay() {
    const slider = container.querySelector("#learning-rate");
    const display = container.querySelector("#learning-rate-value");
    display.textContent = parseFloat(slider.value).toFixed(5);
  }

  // バリデーション関数
  function validateForm() {
    const errors = [];

    // モデル名チェック
    const modelName = container.querySelector("#model-name").value.trim();
    if (!modelName) {
      errors.push("モデル名を入力してください");
    }

    // 対象店舗チェック
    const targetStore = container.querySelector("#target-store").value;
    if (!targetStore) {
      errors.push("対象店舗を選択してください");
    }

    // 商品カテゴリチェック
    const categories = container.querySelectorAll("#product-categories input:checked");
    if (categories.length === 0) {
      errors.push("商品カテゴリを選択してください");
    }

    // 学習期間チェック
    const startDate = container.querySelector("#learning-start").value;
    const endDate = container.querySelector("#learning-end").value;
    if (!startDate || !endDate) {
      errors.push("学習期間を設定してください");
    } else {
      const start = new Date(startDate);
      const end = new Date(endDate);
      const today = new Date();

      if (start > end) {
        errors.push("開始日は終了日より前の日付を設定してください");
      }
      if (start > today || end > today) {
        errors.push("学習期間に未来の日付は設定できません");
      }
    }

    // データソースチェック
    const dataSources = container.querySelectorAll("#data-sources input:checked");
    if (dataSources.length === 0) {
      errors.push("データソースを選択してください");
    }

    // アルゴリズムチェック
    const algorithm = container.querySelector("#algorithm").value;
    if (!algorithm) {
      errors.push("アルゴリズムを選択してください");
    }

    // 精度目標値チェック
    const accuracyTarget = parseInt(container.querySelector("#accuracy-target").value);
    if (accuracyTarget < 0 || accuracyTarget > 100) {
      errors.push("モデル精度目標値は0-100%の範囲で入力してください");
    }

    // 重み付け合計チェック
    const weightInputs = container.querySelectorAll(".weight-input");
    let weightTotal = 0;
    weightInputs.forEach(input => {
      weightTotal += parseInt(input.value) || 0;
    });
    if (weightTotal !== 100) {
      errors.push("重み付けの合計値は100%にしてください");
    }

    // 季節性パラメータの数値チェック
    const seasonalFactor = container.querySelector("#seasonal-factor").value;
    if (seasonalFactor && isNaN(parseFloat(seasonalFactor))) {
      errors.push("季節性パラメータには数値を入力してください");
    }

    return errors;
  }

  // フォームクリア
  function clearForm() {
    container.querySelector("#model-form").reset();
    container.querySelector("#form-title").textContent = "新規モデル作成";
    container.querySelector("#btn-save").textContent = "モデル作成";
    editingModelId = null;
    updateWeightTotal();
    updateLearningRateDisplay();
  }

  // 2. 初期データ読み込み
  window.aivicApi.list(0).then(rows => {
    if (rows) renderRows(rows);
  });

  // 店舗データ読み込み
  loadStores();

  // 3. 検索ボタンのイベントリスナー
  container.querySelector("#btn-search").addEventListener("click", async () => {
    const keyword = container.querySelector("#input-search").value.trim();
    const rows = await window.aivicApi.list(0);
    if (rows) {
      const filtered = keyword ? 
        rows.filter(r => JSON.stringify(r).toLowerCase().includes(keyword.toLowerCase())) : 
        rows;
      renderRows(filtered);
    }
  });

  // CSVエクスポート
  container.querySelector("#btn-csv-export").addEventListener("click", async () => {
    const rows = await window.aivicApi.list(0);
    if (!rows) return;

    const headers = ["モデル名", "対象店舗名", "商品カテゴリ", "アルゴリズム", "精度目標値", "作成日時"];
    const csvContent = "\uFEFF" + [
      headers.join(","),
      ...rows.map(r => [
        `"${r.モデル名 || ""}"`,
        `"${r.対象店舗名 || ""}"`,
        `"${r.商品カテゴリ || ""}"`,
        `"${r.アルゴリズム || ""}"`,
        `"${r.精度目標値 || ""}"`,
        `"${r.作成日時 || ""}"`
      ].join(","))
    ].join("\n");

    const blob = new Blob([csvContent], { type: "text/csv;charset=utf-8;" });
    const link = document.createElement("a");
    link.href = URL.createObjectURL(blob);
    link.download = "model_config_export.csv";
    link.click();
  });

  // 4. 登録ボタンのイベントリスナー
  container.querySelector("#btn-save").addEventListener("click", async (e) => {
    e.preventDefault();

    const errors = validateForm();

    // 既存のエラーメッセージを削除
    container.querySelectorAll(".error-message").forEach(el => el.remove());

    if (errors.length > 0) {
      const errorDiv = document.createElement("div");
      errorDiv.className = "error-message";
      errorDiv.innerHTML = errors.map(err => `• ${err}`).join("<br>");
      container.querySelector(".form-actions").insertBefore(errorDiv, container.querySelector(".form-actions").firstChild);
      return;
    }

    // フォームデータ収集
    const categories = Array.from(container.querySelectorAll("#product-categories input:checked"))
      .map(cb => cb.value).join(", ");
    const dataSources = Array.from(container.querySelectorAll("#data-sources input:checked"))
      .map(cb => cb.value).join(", ");
    const predictionPeriod = container.querySelector("input[name='prediction-period']:checked").value;

    const formData = {
      モデル名: container.querySelector("#model-name").value.trim(),
      対象店舗ID: container.querySelector("#target-store").value,
      対象店舗名: container.querySelector("#target-store").selectedOptions[0]?.textContent || "",
      商品カテゴリ: categories,
      学習期間開始日: container.querySelector("#learning-start").value,
      学習期間終了日: container.querySelector("#learning-end").value,
      予測期間: predictionPeriod,
      データソース: dataSources,
      アルゴリズム: container.querySelector("#algorithm").value,
      学習率: parseFloat(container.querySelector("#learning-rate").value),
      重み付け設定: JSON.stringify({
        売上履歴: parseInt(container.querySelector("input[data-factor='売上履歴']").value),
        天候要因: parseInt(container.querySelector("input[data-factor='天候要因']").value),
        季節要因: parseInt(container.querySelector("input[data-factor='季節要因']").value),
        イベント要因: parseInt(container.querySelector("input[data-factor='イベント要因']").value)
      }),
      季節係数: parseFloat(container.querySelector("#seasonal-factor").value),
      異常値除外フラグ: container.querySelector("#exclude-outliers").checked,
      精度目標値: parseInt(container.querySelector("#accuracy-target").value),
      作成日時: new Date().toISOString(),
      更新日時: new Date().toISOString()
    };

    let result;
    if (editingModelId) {
      result = await window.aivicApi.update(0, editingModelId, formData);
    } else {
      result = await window.aivicApi.save(0, formData);
    }

    if (result) {
      const successDiv = document.createElement("div");
      successDiv.className = "success-message";
      successDiv.textContent = editingModelId ? 
        "モデル設定が正常に変更されました" : 
        "モデルが正常に作成されました";
      container.querySelector(".form-actions").insertBefore(successDiv, container.querySelector(".form-actions").firstChild);

      clearForm();
      const rows = await window.aivicApi.list(0);
      if (rows) renderRows(rows);
    }
  });

  // キャンセルボタン
  container.querySelector("#btn-cancel").addEventListener("click", () => {
    clearForm();
  });

  // 重み付け入力の監視
  container.querySelectorAll(".weight-input").forEach(input => {
    input.addEventListener("input", updateWeightTotal);
  });

  // 学習率スライダーの監視
  container.querySelector("#learning-rate").addEventListener("input", updateLearningRateDisplay);

  // 5. 行レベル操作のイベントデリゲーション
  container.addEventListener("click", async (e) => {
    // 削除ボタン
    const deleteBtn = e.target.closest(".delete-btn");
    if (deleteBtn) {
      if (!confirm("このモデルを削除しますか？")) return;

      await window.aivicApi.delete(0, deleteBtn.dataset.id);
      const rows = await window.aivicApi.list(0);
      if (rows) renderRows(rows);
      return;
    }

    // 編集ボタン
    const editBtn = e.target.closest(".edit-btn");
    if (editBtn) {
      const rows = await window.aivicApi.list(0);
      if (!rows) return;

      const model = rows.find(r => r.id === editBtn.dataset.id);
      if (!model) return;

      // フォームに値を設定
      container.querySelector("#model-name").value = model.モデル名 || "";
      container.querySelector("#target-store").value = model.対象店舗ID || "";

      // 商品カテゴリ設定
      const categories = (model.商品カテゴリ || "").split(", ");
      container.querySelectorAll("#product-categories input").forEach(cb => {
        cb.checked = categories.includes(cb.value);
      });

      // 学習期間設定
      container.querySelector("#learning-start").value = model.学習期間開始日 || "";
      container.querySelector("#learning-end").value = model.学習期間終了日 || "";

      // 予測期間設定
      if (model.予測期間) {
        const periodRadio = container.querySelector(`input[name='prediction-period'][value='${model.予測期間}']`);
        if (periodRadio) periodRadio.checked = true;
      }

      // データソース設定
      const dataSources = (model.データソース || "").split(", ");
      container.querySelectorAll("#data-sources input").forEach(cb => {
        cb.checked = dataSources.includes(cb.value);
      });

      // その他の設定
      container.querySelector("#algorithm").value = model.アルゴリズム || "";
      container.querySelector("#learning-rate").value = model.学習率 || 0.01;
      container.querySelector("#seasonal-factor").value = model.季節係数 || 100;
      container.querySelector("#exclude-outliers").checked = model.異常値除外フラグ || false;
      container.querySelector("#accuracy-target").value = model.精度目標値 || 85;

      // 重み付け設定
      if (model.重み付け設定) {
        try {
          const weights = JSON.parse(model.重み付け設定);
          Object.keys(weights).forEach(factor => {
            const input = container.querySelector(`input[data-factor='${factor}']`);
            if (input) input.value = weights[factor];
          });
        } catch (e) {
          console.warn("重み付け設定のパースに失敗:", e);
        }
      }

      // フォームタイトル変更
      container.querySelector("#form-title").textContent = "モデル設定変更";
      container.querySelector("#btn-save").textContent = "保存";
      editingModelId = editBtn.dataset.id;

      updateWeightTotal();
      updateLearningRateDisplay();

      // フォームまでスクロール
      container.querySelector("#model-form").scrollIntoView({ behavior: "smooth" });
    }
  });

  // 初期値設定
  updateWeightTotal();
  updateLearningRateDisplay();
}
